  const toasts = async (fn) => { const seen = []; const timer = setInterval(() => { for (const n of document.querySelectorAll('.notification-message')) { const x = n.textContent || ''; if (x && !seen.includes(x)) seen.push(x); } }, 40);
    try { await fn(); await sleep(250); } finally { clearInterval(timer); } return seen; };
  const closeChat = async () => { const btn = document.getElementById('minigame-cancel') || document.getElementById('minigame-close'); if (btn && t.getState().activeMinigame) btn.click(); await sleep(400);
    const done = document.querySelector('.pretext-debrief-done'); if (done) done.click(); const end = Date.now() + 5000; while (t.getState().activeMinigame && Date.now() < end) await sleep(100); };
  const openCall = async (cls, callId) => { const mg = window.MinigameFramework.currentMinigame; if (!mg || !mg.container) return false; const begin = mg.container.querySelector('.pretext-begin'); if (!begin) return false; begin.click();
    const end = Date.now() + 15000; while (Date.now() < end) { const c = window.MinigameFramework.currentMinigame; if (c && c.constructor && c.constructor.name === cls && c.params && c.params.pretextCallId === callId) return true; await sleep(150); } return false; };
  const mg = window.MinigameFramework.currentMinigame; const ms = window.mailState; const sentN = () => (ms.mailboxes.guest.messages || []).filter(m => m.folder === 'sent').length; const jobs0 = (ms.jobs || []).length;
