  return seen.some(x => /Gwen Harlow will not read your mail right now/.test(x)) && sentN() === 1 && G().phish_gwen_attempts === 1 && (ms.jobs || []).length === jobs0
    && !mg.getTestState().overlay.layers.includes('checklist') && !mg.checklistPanel && mg.getTestState().overlay.layers.includes('compose'); }

